async def act(page):
    # Modify order #65 shipping address to: 789 Pine Lane, San Francisco, CA, 94102
    # Knowledge-base functions: none are available in the provided knowledge base, so none are used.

    # 1) Locate the order row for 000000065 and get the View link href.
    try:
        order_row = page.get_by_role("row", name="000000065")
        if await order_row.count() == 0:
            # If the row is not present, nothing to do from this state
            return
        view_link = order_row.get_by_role("link", name="View")
        if await view_link.count() == 0:
            return
        href = await view_link.first.get_attribute("href")
        if not href:
            return
    except Exception:
        return

    # 2) Navigate to the order view page using the href (relative goto when possible).
    await page.goto(href)
    await page.wait_for_load_state("networkidle")

    # 3) On the order view page, open editing for the Shipping Address.
    # Prefer targeting the Shipping Address group, then the Edit link/button inside it.
    shipping_group = None
    try:
        shipping_group = page.get_by_role("group", name="Shipping Address")
        if await shipping_group.count() > 0:
            # Try link "Edit" inside the shipping group first
            edit_link = shipping_group.get_by_role("link", name="Edit")
            if await edit_link.count() > 0:
                await edit_link.first.click()
                await page.wait_for_load_state("networkidle")
            else:
                # Try button named Edit inside the group
                edit_btn = shipping_group.get_by_role("button", name="Edit")
                if await edit_btn.count() > 0:
                    await edit_btn.first.click()
                    await page.wait_for_load_state("networkidle")
        else:
            shipping_group = None
            # Fallback: use the second global Edit link (commonly billing then shipping)
            edits = page.get_by_role("link", name="Edit")
            if await edits.count() >= 2:
                await edits.nth(1).click()
                await page.wait_for_load_state("networkidle")
            elif await edits.count() == 1:
                await edits.first.click()
                await page.wait_for_load_state("networkidle")
            else:
                edit_buttons = page.get_by_role("button", name="Edit")
                if await edit_buttons.count() > 0:
                    await edit_buttons.first.click()
                    await page.wait_for_load_state("networkidle")
    except Exception:
        # proceed even if clicking Edit failed; fields might already be editable
        pass

    # 4) Scope subsequent field edits to the shipping_group if present; otherwise use page.
    container = shipping_group if (shipping_group is not None and await shipping_group.count() > 0) else page

    # Helper to fill the first matching textbox by accessible name list within a container locator
    async def fill_first_textbox(container_locator, candidate_names, value):
        for n in candidate_names:
            try:
                tb = container_locator.get_by_role("textbox", name=n)
                if await tb.count() > 0:
                    await tb.first.fill(value)
                    return True
            except Exception:
                continue
        return False

    # 5) Fill Street (may be one or multiple lines). Fill the first matching street field.
    street_names = [
        "Street",
        "Street Address",
        "Street 1",
        "Street 0",
        "Address",
        "Address 1",
        "Shipping Street",
        "Shipping Address",
    ]
    await fill_first_textbox(container, street_names, "789 Pine Lane")

    # 6) Fill City
    city_names = ["City", "Town/City", "Shipping City", "City/Town"]
    await fill_first_textbox(container, city_names, "San Francisco")

    # 7) Fill Postcode / Zip
    postcode_names = ["Zip/Postal Code", "Postcode", "ZIP", "Postal Code", "Zip"]
    await fill_first_textbox(container, postcode_names, "94102")

    # 8) Region/State: try combobox (select) first, then textbox fallback.
    region_combobox_names = ["State/Province", "Region", "State", "Region/State"]
    region_set = False
    for rn in region_combobox_names:
        try:
            combo = container.get_by_role("combobox", name=rn)
            if await combo.count() > 0:
                # Use select_option on the combobox locator
                try:
                    await combo.first.select_option(label="California")
                except Exception:
                    try:
                        await combo.first.select_option(label="CA")
                    except Exception:
                        pass
                region_set = True
                break
        except Exception:
            continue

    if not region_set:
        region_text_names = ["Region", "State", "State/Province", "Region/State", "Province"]
        await fill_first_textbox(container, region_text_names, "CA")

    # 9) Save the address changes. Try Save inside the container first, then page-level fallbacks.
    saved = False
    save_candidates = ["Save Address", "Save", "Submit", "OK"]
    for sname in save_candidates:
        try:
            btn = container.get_by_role("button", name=sname)
            if await btn.count() > 0:
                await btn.first.click()
                saved = True
                break
        except Exception:
            continue

    if not saved:
        for sname in save_candidates:
            try:
                btn = page.get_by_role("button", name=sname)
                if await btn.count() > 0:
                    await btn.first.click()
                    saved = True
                    break
            except Exception:
                continue

    if not saved:
        try:
            all_buttons = page.get_by_role("button")
            if await all_buttons.count() > 0:
                await all_buttons.first.click()
                saved = True
        except Exception:
            pass

    # Wait for potential save completion
    await page.wait_for_load_state("networkidle")

    # End of actions. Attempted to update the shipping address for order #65.

